static const struct RFStoryScene sScenes[] = {
    {0, 1, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Una placa llegó sin procedencia.\nIria copia marcas en Ruta 4;\ppregúntale si reconoce su\ndibujo. No retires nada de la\pmontaña."), COMPOUND_STRING("Iria reconoce el trazo de una\nantigua cantera. La\pinvestigación empieza con una\nprocedencia, no con una leyenda.")},
    {1, 2, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La placa salió de una\nescombrera. Edda compara rocas\pen Monte Moon. Una Piedra Lunar\nayudará a separar las marcas\pnaturales de las talladas."), COMPOUND_STRING("Edda distingue tres técnicas.\nUna sola pieza no demuestra que\ptoda Kanto perteneciera a un\nmismo pueblo.")},
    {2, 2, RF_STORY_CLUES, 0, 0x00000007, COMPOUND_STRING("Compara los atriles de Monte\nMoon B2, Túnel Roca B1 y el\plaboratorio de Canela. Anota los\ntres antes de presentar una\pconclusión."), COMPOUND_STRING("Los tres calcos quedan\narchivados juntos. Las marcas\pviajaron con sus artesanos; no\neran un mapa de conquista.")},
    {2, 0, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El laboratorio puede recuperar\nun Aerodactyl del Ámbar Viejo.\pMuéstralo a Alma: estudiar un\nser vivo exige cuidado, no solo\pentusiasmo."), COMPOUND_STRING("Alma separa hechos y conjeturas\nen la exposición. Tu Aerodactyl\ppermanece contigo; el museo\nconserva únicamente sus\pobservaciones.")},
    {0, 3, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Las copias se compartirán con el\narchivo de Celio. Cuando seas\pCampeón, busca a Nilo en el\nCentro Pokémon de Isla Uno."), COMPOUND_STRING("Nilo recibe el informe y permite\ncontrastarlo con los archivos de\pSete. No necesita extraer una\nsola piedra de las ruinas.")},
    {3, 4, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Tala estudia cómo cambian los\nsignos entre islas. Lleva un\pUnown para comparar sus formas;\nno lo entregarás ni lo dejarás\pen las ruinas."), COMPOUND_STRING("Tala encuentra diferencias entre\nlos signos. Los Unown ayudan a\pleerlos, pero no convierten una\ninterpretación en verdad\pabsoluta.")},
    {4, 5, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("El atril ordena tres etapas:\nprimero roca, después agua y al\pfinal vida. Lee sus preguntas en\nla Cámara Monan. Puedes volver a\pintentarlo."), COMPOUND_STRING("La secuencia abre el índice de\nla cámara, no una puerta\psellada. El índice describe\nintercambios entre comunidades,\psin un reino perdido.")},
    {4, 0, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lleva las conclusiones a Alma.\nLa exposición debe explicar qué\psabemos, qué ignoramos y por qué\nlas piezas siguen en sus\plugares."), COMPOUND_STRING("La sala dedica su nueva cartela\na las comunidades de Kanto y\pSete. El expediente queda\nabierto a futuras preguntas,\ppero esta investigación\nconcluye.")},
    {6, 7, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Una remesa usa la dirección de\nBill sin permiso. Leila teme que\palguien esté suplantando a sus\nclientes. Conserva los datos y\pconsulta a Tomás."), COMPOUND_STRING("La dirección fue copiada de un\narchivo viejo. Tomás advierte a\pBill y separa esa copia de la\nred actual.")},
    {7, 8, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Cuando Silph vuelva a trabajar\ncon normalidad, Ivo podrá\previsar el envío. No entres en\nzonas cerradas para adelantar la\pinvestigación."), COMPOUND_STRING("Ivo conserva el registro y\nconfirma que un intermediario de\pAzulona usó el archivo. Las\ncomunicaciones personales quedan\pfuera del análisis.")},
    {8, 9, RF_STORY_BATTLE, TRAINER_RF_STORY_0, 0x00000000, COMPOUND_STRING("Lio aceptó transportar paquetes\nsin conocer su contenido. Quiere\pcomprobar si puedes acompañarlo\nsin depender de quienes le\ppagaban. Su combate es\nvoluntario."), COMPOUND_STRING("Lio rompe su contrato y entrega\nlas etiquetas. No revela\pdirecciones privadas: solo la\nruta de los paquetes.")},
    {9, 7, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Las etiquetas parecen señalar a\nun Pokémon digital. Lleva una\pcopia a Tomás; perseguir a un\nPorygon no es una forma de pedir\payuda."), COMPOUND_STRING("Bill y Tomás sustituyen las\nclaves expuestas. El problema\pera el permiso de acceso, no la\nexistencia de Porygon.")},
    {7, 10, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Vera necesita comprobar una\ninstalación sin capturar a los\pPokémon que viven allí. Acércale\nun compañero eléctrico dispuesto\pa colaborar."), COMPOUND_STRING("Vera prueba una alimentación\naislada. La Central conserva su\phábitat y deja de ser una excusa\npara encerrar Pokémon.")},
    {10, 8, RF_STORY_CLUES, 0, 0x00000038, COMPOUND_STRING("Antes de conectar nada, revisa\nlos nodos de Silph 1F, la casa\pde Bill y el laboratorio de\nCanela. Las tres comprobaciones\pforman un único informe."), COMPOUND_STRING("Ivo recibe las tres\nverificaciones. La nueva copia\ptiene procedencia y permisos\nclaros; una avería no borrará el\ptrabajo de los demás.")},
    {8, 7, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Registra a Porygon en tu Pokédex\ny consulta a Tomás. El estudio\putiliza tus observaciones; tu\nPokémon no se transfiere a\pningún ordenador."), COMPOUND_STRING("Tomás documenta cómo colaborar\ncon Porygon sin confundirlo con\puna herramienta desechable.")},
    {7, 11, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ya como Campeón, revisa la\nterminal del antiguo almacén\pRocket de Isla Cinco. Debes\nllegar por los accesos normales\pde tu aventura."), COMPOUND_STRING("La terminal queda aislada y el\narchivo limpio vuelve a Silph.\pBill conserva una copia de\nemergencia. La red ya no depende\pde una clave robada.")},
    {12, 13, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Cuando el señor Fuji esté a\nsalvo, visita a Inés en su casa\pde Pueblo Lavanda. Un Cubone del\nrefugio evita los ruidos del\pexterior."), COMPOUND_STRING("Inés te presenta al pequeño sin\nforzarlo a acercarse. Ayudar\pcomienza por respetar la\ndistancia que pide.")},
    {13, 12, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Un compañero de su especie puede\nhacer la visita más tranquila.\pLleva Cubone o Marowak a Rosa,\nsin entregarle tu Pokémon."), COMPOUND_STRING("Rosa observa un primer\nacercamiento. Tu compañero\pvuelve contigo; el pequeño del\nrefugio empieza a reconocer\pvoces amigas.")},
    {12, 14, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Darío conoce un tramo tranquilo\nde Ruta 12. Pídele que revise el\pcamino antes de organizar un\npaseo con el refugio."), COMPOUND_STRING("Darío retira su equipo de pesca\ndel paso. Inés podrá acompañar\pal grupo sin obligarlo a\natravesar una multitud.")},
    {14, 15, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Zaira preparará objetos para que\nel pequeño elija cómo jugar.\pLleva una Pokémuñeca a la\noficina del Safari; se consume\psolo al confirmar."), COMPOUND_STRING("Zaira incorpora la muñeca al\nmaterial del refugio. Nadie\pexige que Cubone juegue con ella\nni que deje su hueso.")},
    {15, 13, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("La salida requiere un botiquín\npara todo el grupo. Inés\pnecesita un Antídoto; comprarlo\no encontrarlo sirve, y la\pentrega queda registrada."), COMPOUND_STRING("El botiquín queda preparado. El\ncuidado cotidiano permite que el\prefugio organice más paseos sin\nasumir riesgos innecesarios.")},
    {13, 12, RF_STORY_CLUES, 0, 0x000001C0, COMPOUND_STRING("Lee los memoriales de las\nplantas 5, 6 y 7 de la Torre\pPokémon. Rosa reunirá las tres\nnotas en un solo recuerdo, sin\pllevarse sus ofrendas."), COMPOUND_STRING("Rosa prepara un recuerdo con\npermiso del refugio. La historia\pno borra la pérdida; deja\nespacio para hablar de ella.")},
    {12, 14, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El grupo ha realizado su primer\npaseo acompañado. Pregunta a\pDarío cómo fue y lleva noticias\na quienes esperan, sin buscar al\ppequeño por tu cuenta."), COMPOUND_STRING("Darío cuenta que Cubone quiso\nregresar antes que los demás. El\pgrupo lo respetó; elegir volver\ntambién es ganar confianza.")},
    {14, 13, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El refugio tiene una nueva\nrutina. Visita a Inés para\pcerrar el informe y saber qué ha\nelegido hacer Cubone."), COMPOUND_STRING("Cubone decide quedarse con Inés\ny salir con el grupo cuando le\papetezca. Puedes visitarlo aquí.\nTu Pokémon nunca fue entregado\pal refugio.")},
    {16, 17, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La Pokédex de Oak necesita\nobservaciones de campo. Registra\pCaterpie y visita a Silva en\nBosque Verde para aprender cómo\panotar su hábitat."), COMPOUND_STRING("Silva registra luz, refugio y\nalimento. La ficha de Caterpie\pya no es solo un número.")},
    {17, 18, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Compara la vida del bosque con\nla de una cueva. El geólogo\pBruno te espera en Túnel Roca B1\ncuando tengas el registro de\pGeodude."), COMPOUND_STRING("Bruno distingue huellas\nrecientes de marcas antiguas. El\pgrupo evita usar un nido como\nzona de descanso.")},
    {18, 19, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mar estudia los lugares donde\ndescansan los Pokémon de la\pcosta. Registra Seel antes de\nconsultar sus notas en Islas\pEspuma."), COMPOUND_STRING("Mar añade zonas de descanso al\ninforme. Los investigadores\pcambian su recorrido para no\nocuparlas.")},
    {19, 20, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El Safari necesita comparar sus\ncuidados con los hábitats\psilvestres. Registra Nidoran\nhembra y habla con Salo en la\poficina de Fucsia."), COMPOUND_STRING("Salo corrige el plano de\nrefugios. La conclusión\pdistingue lo observado de lo que\naún debe comprobarse.")},
    {20, 10, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El comportamiento eléctrico\ntambién depende del entorno.\pRegistra Voltorb y contrasta sus\nlugares de descanso con Vera en\pla Central."), COMPOUND_STRING("Vera anota distancias seguras\npara sus pruebas. La\pinvestigación de Oak y la\nreparación de la red comparten\pobservaciones, no Pokémon.")},
    {10, 21, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nora compara los refugios\ncálidos de Isla Uno. Registra\pPonyta y lleva la ficha a Camino\nCandente cuando puedas viajar a\pSete."), COMPOUND_STRING("Nora encuentra que descanso y\ntemperatura deben anotarse\pjuntos. Un dato aislado no\nexplica todo el comportamiento.")},
    {21, 16, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ada reunirá las notas de bosque,\ncueva, costa, Safari, Central e\pislas. Vuelve al laboratorio de\nPaleta para revisar sus\pdiferencias."), COMPOUND_STRING("Ada conserva las discrepancias\nen vez de borrarlas. El archivo\pde Oak explica cómo se obtuvo\ncada dato.")},
    {16, 16, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Revisa las conclusiones con Ada.\nLos demás registros de Pokédex\pseguirán ampliando el archivo;\nno tienes que completarlos todos\ppara cerrar esta campaña."), COMPOUND_STRING("Oak recibe el estudio y Ada\nfirma también tu trabajo. La\pinvestigación concluye con una\nmetodología que otros podrán\prepetir.")},
    {22, 23, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Un excursionista pidió ayuda\nantes de entrar en Monte Moon.\pPaz organiza el puesto de Ruta 3\ny necesita una Poción para su\pbotiquín."), COMPOUND_STRING("Paz prepara el puesto sin enviar\na nadie solo a la cueva. Avisar\pa tiempo ha evitado una búsqueda\nnocturna.")},
    {23, 1, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Paz ha recibido dos indicaciones\ndistintas sobre una salida. Iria\pestá comprobando las señales de\nRuta 4; habla con ella antes de\pmover al grupo."), COMPOUND_STRING("Iria corrige una copia del\nplano. La patrulla acuerda un\ppunto de regreso que todos\npueden reconocer.")},
    {1, 24, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Teo mantiene a salvo a un\nexcursionista desorientado en\pTúnel Roca. No hace falta\nenfrentarse a él: necesita\pnoticias claras de la salida."), COMPOUND_STRING("Teo puede acompañar al\nexcursionista hasta un punto\pseguro. El rescate queda anotado\ny la familia recibe el aviso.")},
    {24, 24, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("El siguiente turno necesita un\nRepelente para reducir\pencuentros durante el traslado.\nEntrégalo al puesto; no se usa\psobre tu equipo."), COMPOUND_STRING("El relevo recibe el material y\nconfirma la salida. Teo conserva\psu puesto para orientar a otros\nviajeros.")},
    {24, 25, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Rubén reúne los avisos para las\nfamilias de los excursionistas.\pLleva la confirmación a Ciudad\nFucsia, sin dar por desaparecido\pa nadie más."), COMPOUND_STRING("Rubén cierra la búsqueda y\nconserva los teléfonos de\pcontacto. La familia ya sabe que\nel grupo está de regreso.")},
    {25, 26, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Yara pide comparar señales en\nBosque Baya, en Isla Tres. La\ppatrulla trabaja después del\nrescate de Pedrita y no\psustituye aquella historia."), COMPOUND_STRING("Yara confirma una ruta de\nretorno y mantiene una patrulla\pvisible. Los nuevos visitantes\ntendrán un punto al que pedir\payuda.")},
    {26, 15, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La patrulla necesita pautas para\nayudar a Pokémon asustados sin\pacorralarlos. Zaira revisará las\nnotas en la oficina del Safari."), COMPOUND_STRING("Zaira incorpora una distancia de\nseguridad a las instrucciones.\pLa red aprende de cada rescate,\nen vez de limitarse a contarlos.")},
    {15, 22, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lina espera los informes de las\npatrullas. Vuelve a Ciudad Verde\ppara dejar acordados los puestos\nde auxilio y los avisos a las\pfamilias."), COMPOUND_STRING("Los puestos quedan coordinados.\nLina abre encargos de\pprovisiones repetibles,\nseparados de esta campaña y con\pun límite diario.")},
    {6, 27, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Leila trae una invitación de\nintercambio para una entrenadora\pde Johto. Hana espera en Ciudad\nCarmín y decidirá si quiere\pparticipar."), COMPOUND_STRING("Hana acepta intercambiar\napuntes. Nadie apuesta Pokémon\pni condiciona tu paso por la\nciudad.")},
    {27, 27, RF_STORY_BATTLE, TRAINER_RF_STORY_1, 0x00000000, COMPOUND_STRING("Hana quiere estudiar cómo\nrespondes a un equipo de apoyo.\pPuedes rechazar el combate y\nretomarlo cuando tu equipo esté\ppreparado."), COMPOUND_STRING("Hana anota tus decisiones y te\nentrega una copia de su\pestrategia. El intercambio\ncontinúa con Ken, en Azulona.")},
    {27, 28, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ken trae observaciones de Hoenn.\nCompara con él cómo cambia un\pequipo cuando no puede depender\nde un único movimiento."), COMPOUND_STRING("Ken comparte sus notas y propone\nuna práctica. Su objetivo es\pmostrar alternativas, no\nmodificar las reglas de tu\ppartida.")},
    {28, 28, RF_STORY_BATTLE, TRAINER_RF_STORY_2, 0x00000000, COMPOUND_STRING("Ken ha preparado un equipo con\nrespuestas distintas a un mismo\prival. El combate es opcional y\npodrás volver si pierdes."), COMPOUND_STRING("Ken encuentra una debilidad en\nsus propios apuntes. Ambos\pconservan sus equipos y sus\nreglas habituales.")},
    {28, 29, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mael quiere contrastar sus\nanotaciones de Sinnoh con las\ptuyas. Te espera en Azafrán\ndespués de obtener seis\pmedallas."), COMPOUND_STRING("Mael reserva espacio para los\nerrores de su hipótesis. Propone\pcomprobarla contigo en un\ncombate de práctica.")},
    {29, 29, RF_STORY_BATTLE, TRAINER_RF_STORY_3, 0x00000000, COMPOUND_STRING("Una hipótesis también debe\nsobrevivir a una derrota. Mael\pha preparado un equipo\nequilibrado; vuelve cuando\pquieras intentar su práctica."), COMPOUND_STRING("Mael corrige su propuesta sin\natribuir el resultado a una\pregión. Sus notas pasan a formar\nparte del intercambio.")},
    {29, 30, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Sara reúne el intercambio final\nen Isla Siete. Cuando seas\pCampeón, llévale los cuadernos\nde Hana, Ken y Mael."), COMPOUND_STRING("Sara descubre que los cuadernos\ncoinciden en escuchar al\pcompañero. Propone un último\ncombate sin apuestas ni cambios\ppermanentes.")},
    {30, 30, RF_STORY_BATTLE, TRAINER_RF_STORY_4, 0x00000000, COMPOUND_STRING("Sara quiere cerrar el\nintercambio en combate. Puedes\pintentarlo varias veces; cada\nderrota conserva el progreso de\plos demás encuentros."), COMPOUND_STRING("Los cuatro visitantes firman el\ncuaderno compartido. No hay una\pescuela vencedora: quedan\nestrategias que otros\pentrenadores podrán discutir.")},
    {31, 33, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mara ha encontrado una lista de\nobjetos sin propietarios. La\pprimera anotación apunta a una\nplaca de Cabo Extremo, en Isla\pDos."), COMPOUND_STRING("La placa vincula el inventario\ncon antiguas rutas de ayuda. No\pseñala un cofre: enumera lo que\ndebía devolverse.")},
    {33, 32, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La lista menciona un pilar\nlevantado en memoria de quienes\pfaltan. Lee su baliza en Isla\nCinco sin tocar las ofrendas."), COMPOUND_STRING("La baliza conserva los nombres\nde una tripulación. Mara podrá\pbuscar a sus familias, en lugar\nde vender lo hallado.")},
    {32, 31, RF_STORY_CLUES, 0, 0x0001C000, COMPOUND_STRING("Busca los tres testimonios\nseñalados en Carmín, Ruta 12 y\pCabo Extremo. Juntos permitirán\nreconstruir el inventario, sin\pconvertir cada nota en un\nencargo."), COMPOUND_STRING("Las tres notas confirman la ruta\ny sus destinatarios. Mara guarda\puna copia pública y protege las\ndirecciones privadas.")},
    {31, 3, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Una Perla común permitirá\nreconstruir una pieza del\pinventario sin usar objetos\núnicos. Nilo preparará una\préplica documentada para las\nfamilias."), COMPOUND_STRING("Nilo identifica la réplica como\ntal. Las familias reciben su\phistoria sin que nadie les venda\nuna antigüedad falsa.")},
    {3, 4, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El último nombre aparece también\nen Valle Ruinas. Tala comprobará\pla lectura sin relacionar\ncualquier ruina con un mismo\pautor."), COMPOUND_STRING("Tala distingue dos personas con\nnombres parecidos. Evita que el\parchivo atribuya la historia a\nla familia equivocada.")},
    {4, 34, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El diario de Leyendas tiene el\nencargo Espíritus de Alola.\pReúne el registro de sus cuatro\nguardianes y vuelve a Gael. Si\pya lo completaste, tu archivo\nsirve: nadie debe volver a\pcapturarlos."), COMPOUND_STRING("El archivo de los guardianes\nexplica la ruta del sur. Gael\psepara su cuidado del valor del\ninventario; no aparece ningún\pejemplar duplicado.")},
    {34, 31, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El inventario está documentado.\nDevuélvelo a Mara en Carmín para\pque pueda organizar las entregas\na las familias."), COMPOUND_STRING("Mara prepara las devoluciones.\nEl valor de lo encontrado está\pen que vuelva a tener dueño.")},
    {31, 0, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Alma expondrá una copia del\ninventario y explicará qué se\pdevolvió. Visítala en el museo\npara cerrar la búsqueda."), COMPOUND_STRING("La cartela reconoce a las\nfamilias y a quienes mantuvieron\plas rutas de ayuda. El tesoro\nqueda compartido como historia,\pno repartido como botín.")},
    {22, 36, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Riel organiza prácticas de\norientación entre Ruta 22 y\pCiudad Verde. Habla con él: no\nnecesitarás abandonar a ningún\pcompañero."), COMPOUND_STRING("Riel explica el trayecto y sus\npuestos. Si una práctica se\pinterrumpe, se vuelve a empezar\nsin perder el encargo.")},
    {36, 22, RF_STORY_RACE, 0, 0x00000000, COMPOUND_STRING("Inicia la práctica hablando otra\nvez con Riel en Ruta 22. Lleva\psu mensaje a Lina en Ciudad\nVerde antes de 45 segundos.\pPuedes reintentarlo."), COMPOUND_STRING("Lina recibe el mensaje a tiempo.\nUna llegada segura vale más que\pel récord; Riel conserva el\npuesto para nuevas prácticas.")},
    {22, 17, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Silva propone recordar el orden\nroca, agua y vida con un juego\pde preguntas. Un error reinicia\nel juego, no tu aventura."), COMPOUND_STRING("Silva entrega la secuencia\ncorrecta al grupo. El juego\penseña a confirmar señales antes\nde seguir una ruta.")},
    {17, 34, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Ya como Campeón, Gael prepara\nuna expedición de cinco puestos\pen Cañón Sétano. Entrega dos\nSuperrepelentes para la reserva\pcomún."), COMPOUND_STRING("Gael guarda las provisiones de\nla expedición. No se retira tu\pequipo ni se modifica lo que\nllevas equipado.")},
    {34, 34, RF_STORY_CLUES, 0, 0x00003E00, COMPOUND_STRING("Pasa por los cinco puestos\nseñalados de Cañón Sétano y\pregresa a Gael. El cuaderno\nconserva cada puesto visitado\paunque guardes y salgas."), COMPOUND_STRING("Gael comprueba los cinco sellos.\nTodos los puestos conservan una\pindicación de regreso; la\nexpedición no termina en el\plugar más lejano.")},
    {34, 35, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Belén comparará la expedición\ncon su patrulla de Isla Seis.\pLlévale el informe para que\notros puedan escoger una ruta\padecuada."), COMPOUND_STRING("Belén incorpora caminos de\nretorno más cortos para quienes\plos necesiten. La ruta deja de\ndepender de un único guía.")},
    {35, 34, RF_STORY_BATTLE, TRAINER_RF_STORY_5, 0x00000000, COMPOUND_STRING("Gael simula el último encuentro\nde una expedición. Es un combate\pvoluntario con tu equipo\nhabitual; puedes volver a\pprepararte si pierdes."), COMPOUND_STRING("Gael da por finalizada la\npráctica. La prueba no exigía\pagotar recursos, sino reconocer\ncuándo prepararse mejor.")},
    {34, 22, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Entrega a Lina el cuaderno de\norientación y expediciones. Cada\pparticipante ha confirmado su\nregreso; falta cerrar el\pregistro común."), COMPOUND_STRING("Lina archiva la ruta, los cinco\nsellos y el regreso del grupo.\pLa campaña termina con todas las\npersonas localizadas y encargos\pdiarios opcionales.")},
};
static const struct RFStoryContract sContracts[] = {
    {22, 389, ITEM_POTION, 1, ITEM_ORAN_BERRY, 3, COMPOUND_STRING("Poción para la patrulla")},
    {31, 405, ITEM_PEARL, 1, ITEM_NET_BALL, 2, COMPOUND_STRING("Réplica para el archivo")},
    {34, 413, ITEM_SUPER_REPEL, 1, ITEM_GREAT_BALL, 2, COMPOUND_STRING("Reserva de expedición")},
};
